const EXT_TO_LANG: Record<string, string> = {
  ts: 'typescript',
  mts: 'typescript',
  cts: 'typescript',
  tsx: 'react',
  js: 'javascript',
  mjs: 'javascript',
  cjs: 'javascript',
  jsx: 'react',
  py: 'python',
  pyw: 'python',
  rs: 'rust',
  go: 'go',
  lua: 'lua',
  luau: 'lua',
  md: 'markdown',
  mdx: 'markdown',
  markdown: 'markdown',
  json: 'json',
  jsonc: 'json',
  css: 'css',
  scss: 'css',
  less: 'css',
  html: 'html',
  htm: 'html',
  sh: 'shell',
  bash: 'shell',
  zsh: 'shell',
  ps1: 'powershell',
  psm1: 'powershell',
  yml: 'yaml',
  yaml: 'yaml',
  sql: 'sql',
  java: 'java',
  cs: 'csharp',
  cpp: 'cpp',
  cc: 'cpp',
  cxx: 'cpp',
  h: 'cpp',
  hpp: 'cpp',
  rb: 'ruby',
  php: 'php',
  toml: 'toml',
  dockerfile: 'docker',
  xml: 'file',
  svg: 'file',
  txt: 'file',
  log: 'file',
  ini: 'file',
  conf: 'file',
  env: 'file'
}

export function resolveLanguageId(pathOrLang: string): string {
  const raw = (pathOrLang || '').trim()
  if (!raw) return 'file'
  const lower = raw.toLowerCase().replace(/\\/g, '/')
  // Bare language id
  if (LANGS[lower]) return lower
  const base = lower.includes('/') ? lower.slice(lower.lastIndexOf('/') + 1) : lower
  if (base === 'dockerfile') return 'docker'
  if (base === 'makefile') return 'file'
  const ext = base.includes('.') ? base.slice(base.lastIndexOf('.') + 1) : base
  return EXT_TO_LANG[ext] || 'file'
}

export function languageBrandColor(pathOrLang: string): string {
  const id = resolveLanguageId(pathOrLang)
  return LANGS[id]?.brand || LANGS.file.brand
}

export function LanguageIcon({
  pathOrLang,
  size = 14,
  className = '',
  title,
  color
}: Props): JSX.Element {
  const id = resolveLanguageId(pathOrLang)
  const def = LANGS[id] || LANGS.file
  const fill = color || def.brand
  const tip = title || def.label

  // Light brands (JS yellow) need a dark plate so they stay visible on dark UI
  const needsPlate = !color && (id === 'javascript' || id === 'json' || id === 'markdown')

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      className={`language-icon language-icon-${def.id} ${className}`.trim()}
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden={tip ? undefined : true}
      role={tip ? 'img' : undefined}
      focusable={false}
    >
      {tip ? <title>{tip}</title> : null}
      {needsPlate && (
        <rect x="0.5" y="0.5" width="23" height="23" rx="3" fill="#1e293b" />
      )}
      {def.paths ? (
        def.paths.map((p, i) => (
          <path key={i} d={p.d} fill={color || p.fill} />
        ))
      ) : (
        <path d={def.path || LANGS.file.path!} fill={fill} />
      )}
    </svg>
  )
}
